import fs from 'fs';
import path from 'path';
import { FLUTTER_MARKET_FILES } from '../src/markets/flutterMarketProject';

const targetDir = path.resolve(process.argv[2] ?? 'marketpulse_apk_build');

// Clean up default Kotlin DSL Gradle files generated by flutter create >=3.29
const stalePaths = [
  'android/build.gradle.kts',
  'android/settings.gradle.kts',
  'android/app/build.gradle.kts',
  'android/app/src/main/kotlin',
  'test/widget_test.dart',
];

for (const rel of stalePaths) {
  const full = path.join(targetDir, rel);
  if (fs.existsSync(full)) {
    fs.rmSync(full, { recursive: true, force: true });
  }
}

for (const file of FLUTTER_MARKET_FILES) {
  const outPath = path.join(targetDir, file.path);
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, file.content, 'utf8');
}

console.log(
  `Extracted ${FLUTTER_MARKET_FILES.length} MarketPulse Global Flutter Android files into ${targetDir}`
);
